var layerIndex = '2'
var idField = 'detourid'
var idPrefix = 'dt-' 
var digits = 6

/*DO NOT CHANGE ANYTHING BELOW THIS LINE
-------------------------------------------------------------------------*/

function GenerateWildcards(digits, wildcard) {
  var wildcards = ''
  for (var i=0; i < digits; i++) {
    wildcards += wildcard
  }
  return wildcards
} 

function GetNextId(layerIndex, idField, idPrefix, padding, sqlFilter) {
  // get the feature with the greatest assetid that matches the id pattern specified in the SQL statement.
  var assetid_features = Filter(FeatureSetById($datastore, layerIndex, [idField], false), sqlFilter)
  var max_assetid_feature = First(OrderBy(assetid_features, `${idField} DESC`))  

  // If no features match the pattern the featureset will be null, return the first assetid
  if(max_assetid_feature == null) {   
    return `${idPrefix}${Right(padding, Count(padding)-1)}1`
  }

  // when features do match the pattern calculate and return the next assetid  
  var max_assetid = max_assetid_feature[idField]

  var next_assetid_number = Number(Replace(max_assetid, idPrefix, "")) + 1
  return `${idPrefix}${Text(next_assetid_number, padding)}`
}

// Define the edit context so the value is only calculated when the feature is created
if ($editContext.editType == "INSERT") {
  // return matching prefix pattern and get next value
  var wildcards = GenerateWildcards(digits, '_')
  var padding =  GenerateWildcards(digits, '0')
  if (idPrefix != '') {
    var sqlFilter = `${idField} LIKE '${idPrefix}${wildcards}' AND ${idField} NOT LIKE '%[^0-9]'`    
    GetNextId(layerIndex, idField, idPrefix, padding, sqlFilter)
  }

// return number id's only and get next value
  else {
    var sqlFilter = `${idField} NOT LIKE '%[^0-9.]%'`    
    GetNextId(idPrefix, padding, sqlFilter)
  }

}
else {
  return $feature[idField]
}

var roadsItemID = "9df2ddfa696a4271a749aac54d32814d";
var roadsLayerID = 0;
var roadNameField = "name";
var bufferDistance = 10;
var bufferUnit = "meter";

/*DO NOT CHANGE ANYTHING BELOW THIS LINE
-------------------------------------------------------------------------*/
var arcgisPortal = Portal('https://localdeployment.maps.arcgis.com');

// Get all the intersecting roads within the buffer distance of the closure
var closureBuffer = Buffer($feature, bufferDistance, bufferUnit);
var intersectingRoads = Intersects(FeatureSetByPortalItem(arcgisPortal, roadsItemID, roadsLayerID, [roadNameField], true), closureBuffer);

// Get a list of all the unique road names
var uniqueRoadNames = {};
for (var road in intersectingRoads) {
	var roadName = road[roadNameField];
		if (IsEmpty(roadName)) continue;
	if (HasKey(uniqueRoadNames, roadName)) {
		Push(uniqueRoadNames[roadName], road);
	}
	else {
		uniqueRoadNames[roadName] = [road];
	}
}

// Union the road segments with the same road name
// Test if the closure falls completely within the buffer distance of the unioned road segments
var containingRoads = {}
for (var roadName in uniqueRoadNames) {
	var roadUnion = Union(uniqueRoadNames[roadName]);
	var bufferRoadUnion = Buffer(roadUnion, bufferDistance, bufferUnit);
	if (Within($feature, bufferRoadUnion)) containingRoads[roadName] = [roadUnion, uniqueRoadNames[roadName]];
}

// If the closure falls completely within multiple unioned road segements determine which the closure is closest to
var closestRoad = null;
var closestDistance = null;
for (var roadName in containingRoads) {
	var dist = Distance($feature, containingRoads[roadName][0])
	if (IsEmpty(closestDistance) || dist < closestDistance) {
		closestRoad = [roadName, containingRoads[roadName][0], containingRoads[roadName][1]];
		closestDistance = dist;
	}
}

// If there are no unioned road segments with the same name that the closure matches return null
// Otherwise return the closest matching road name
if (IsEmpty(closestRoad)) return null
return closestRoad[0]

